double g(int n, int m, int arr[96][7])
{
// This method will return the correct value for the G function with r = n, and r’ = m
double result = 0;
for(int a = 1; a <= 3; a++) for(int l = 0; l < 12; l++) result += lookup(n, l, a, arr)*lookup(m, l, a, arr);
return result/6;
}

void read(std::fstream& data, int arr[96][7])
{
// This method will read data into the arr in the proper format
for(int i = 0; i < 96; i++) for(int j = 0; j < 7; j++) data >> arr[i][j];
}

